grid[14][5]=1
from collections import deque,defaultdict
R=C=30; comp=[[-1]*C for _ in range(R)]; comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c] and comp[r][c]<0:
   k=len(comps); q=deque([(r,c)]); comp[r][c]=k; cells=[]
   while q:
    y,x=q.popleft(); cells.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     yy,xx=y+dy,x+dx
     if 0<=yy<R and 0<=xx<C and grid[yy][xx] and comp[yy][xx]<0:
      comp[yy][xx]=k;q.append((yy,xx))
   comps.append(cells)
for k,cells in enumerate(comps):
 marks=[(r,c,grid[r][c]) for r,c in cells if grid[r][c]>1]
 print(k,len(cells),marks, (min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells)))

marks_by_comp={k: next((grid[r][c] for r,c in cells if grid[r][c]>1), None) for k,cells in enumerate(comps)}
centers=defaultdict(list)
for r in range(R-2):
 for c in range(C-2):
  vals=[grid[y][x] for y in range(r,r+3) for x in range(c,c+3)]
  if all(vals):
   k=comp[r+1][c+1]
   if marks_by_comp.get(k) is not None:
    centers[k].append((r+1,c+1))
for k, cs in centers.items():
 print('comp',k,'color',marks_by_comp[k],len(cs),cs)
